Validate that the `owner` (if provided in the request body) matches the authenticated user's identity (`authContext.userId`). Currently, any client can specify an arbitrary `owner` in the request body, allowing them to link connections to other users' accounts or perform unauthorized operations.

```suggestion
function assertIdentityMatches(body: Record<string, any>, authContext: RouteAuthContext): void {
  const bodyUserId = asOptionalString(body.userId);
  if (bodyUserId && bodyUserId !== authContext.userId) {
    throw {
      code: 'TENANT_ACCESS_DENIED',
      message: 'identity mismatch',
      status: 403,
    };
  }

  const owner = asConnectionOwner(body.owner);
  if (owner && owner.kind === 'user' && owner.userId !== authContext.userId) {
    throw {
      code: 'TENANT_ACCESS_DENIED',
      message: 'identity mismatch',
      status: 403,
    };
  }

```

