Defensively guard against `undefined` or non-string values of `routePath` in `getMountPrefixFromRoutePath` to prevent potential `TypeError` crashes if the routing context doesn't provide a valid route path.

```typescript
function getMountPrefixFromRoutePath(routePath: string | undefined): string {
  if (!routePath) {
    return '';
  }
  if (routePath.endsWith('/*')) {
    return routePath.slice(0, -2);
  }

  return routePath === '*' ? '' : routePath;
}
```

