Return `undefined` instead of `null` when a cache entry is not found or has expired. This allows `null` to be a valid cached value (e.g., when an action successfully returns `null`), preventing unnecessary cache misses on subsequent requests.

```suggestion
  async get<T>(key: string): Promise<T | undefined> {
    const entry = this.cache.get(key);

    if (!entry) {
      return undefined;
    }

    if (Date.now() > entry.expiresAt) {
      this.cache.delete(key);
      return undefined;
    }

    this.logger?.debug(`Cache hit: ${key}`);
    return entry.data;
  }
```

